const p = msg.payload;
if (p && p.source === 'high') {
    // Therm-mode HIGH_Alert tripped: room above THIGH, start cooling.
    return [{ payload: 'ALERT: server room above 30 °C' }, { payload: true }];
}
if (p && p.temperature_c !== undefined) {
    // HIGH_Alert stays latched in Therm mode until the room drops below
    // TLOW, so it doubles as the fan state and switches the fan off again.
    msg.payload = `${p.temperature_c.toFixed(3)} °C` + (p.high_alert ? ' (cooling)' : '');
    return [msg, { payload: p.high_alert }];
}
return null;
